#[cfg(test)]
mod conformance {
    //! Round-trip tests harvested from the spec's `spec.md`,
    //! plus a `rejects_invalid_examples` test for any fixtures
    //! in `payload.invalid-examples.json` (validate feature).
    #[test]
    fn request_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:6d8f0a12-3b5c-4e7f-9a1b-2c3d4e5f6a01\",\n  \"type\": \"https://trusttasks.org/spec/webvh/witness/key/create/0.1\",\n  \"issuer\": \"did:webvh:QmAdminScid1:admin.example.com:alice\",\n  \"recipient\": \"did:webvh:QmWitnessScid6:witness.example.com\",\n  \"issuedAt\": \"2026-09-27T09:40:00Z\",\n  \"payload\": { \"label\": \"EU witness 1\" }\n}\n";
        let doc: crate::TrustTask<super::Payload> =
            serde_json::from_str(JSON).expect("deserialize request example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "request example failed round-trip");
    }
    #[test]
    fn response_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:6d8f0a12-3b5c-4e7f-9a1b-2c3d4e5f6a02\",\n  \"type\": \"https://trusttasks.org/spec/webvh/witness/key/create/0.1#response\",\n  \"threadId\": \"urn:uuid:6d8f0a12-3b5c-4e7f-9a1b-2c3d4e5f6a01\",\n  \"issuer\": \"did:webvh:QmWitnessScid6:witness.example.com\",\n  \"recipient\": \"did:webvh:QmAdminScid1:admin.example.com:alice\",\n  \"issuedAt\": \"2026-09-27T09:40:01Z\",\n  \"payload\": {\n    \"key\": {\n      \"witnessId\": \"w-01J8Z6Q4M2\",\n      \"did\": \"did:key:z6MkWitness\",\n      \"label\": \"EU witness 1\",\n      \"createdAt\": \"2026-09-27T09:40:01Z\",\n      \"proofsSigned\": 0\n    }\n  }\n}\n";
        let doc: crate::TrustTask<super::Response> =
            serde_json::from_str(JSON).expect("deserialize response example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "response example failed round-trip");
    }
    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            ("Empty label.", "{\n  \"label\": \"\"\n}"),
            (
                "Producer-supplied key material is not accepted — the witness service generates the key.",
                "{\n  \"privateKeyMultibase\": \"z3u2...\"\n}",
            ),
            (
                "Label over 256 characters.",
                "{\n  \"label\": \"xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\"\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
}
